    let mut w0: i32 = 0;
    let mut wi: i32 = 0;
    let mut wn: i32 = 0;
    let mut ts: i32 = 0;
    let mut tl: i32 = 0;
    let mut j: i32 = 0;
    let mut r: i32 = 0;
    let mut lnx: i32 = 0;
    let mut lx0: i32 = 0;
    let mut ly0: i32 = 0;
    let mut lx1: i32 = 0;
    let mut ly1: i32 = 0;
    let mut bx0: i32 = 0;
    let mut by0: i32 = 0;
    let mut bx1: i32 = 0;
    let mut by1: i32 = 0;
    let mut ymid: i32 = 0;
    let mut asc: i32 = 0;
    let mut dsc: i32 = 0;
    let mut size: i32 = 0;
    let mut rot: i32 = 0;
    let mut dir: i32 = 0;
    let mut gap: i32 = 0;
    let mut first: i32 = 0;
    let mut ox: i32 = 0;
    let mut ox1: i32 = 0;
    let mut nx0: i32 = 0;
    let mut xm: i32 = 0;
    let mut commas: i32 = 0;
    let mut dollars: i32 = 0;
    let mut nx1: i32 = 0;
