pub fn sc_emit_lines(olines: &mut crate::port::Cells, owords: &mut crate::port::Cells, osyms: &mut crate::port::Cells, l0: i32, nl: i32, page: i32, rotmed: i32, mut scr: &mut crate::port::Cells, mut words: &mut crate::port::Cells, mut lines: &mut crate::port::Cells) -> i32 {
    // Every OCR line of the run [l0, l0 + nl) that has words as a `lines` row, and its words as `words` rows, in the arenas
    // the text layer fills (D213: size, box and rotation are the line's, see the head of this file). The words' text is
    // the shared `etext`'s: `hd-tstart` and `hd-tlen` of an OCR word are read as they are. Answers the lines made.
    return sc_emit_core(olines, owords, osyms, l0, nl, page, rotmed, scr, words, lines, 0);
}
pub fn sc_emit_sel(olines: &mut crate::port::Cells, mut owords: &mut crate::port::Cells, osyms: &mut crate::port::Cells, nsel: i32, page: i32, rotmed: i32, mut scr: &mut crate::port::Cells, mut words: &mut crate::port::Cells, mut lines: &mut crate::port::Cells, mut etext: &mut crate::port::Cells, rules: &mut crate::port::Cells, comps: &mut crate::port::Cells, inks: &mut crate::port::Cells) -> i32 {
    // `sc-emit-lines` over the OCR lines the scratch names (P7.4): `nsel` `olines` rows, in the order to emit them, at `scr`
    // cells `sc-sel-base` and up (`sc-sel-set`; `sc-prep` makes room for `sc-sel-max` of them): the lines of several runs chosen
    // line by line, their size clustered over the chosen lines; and (P12.6, `sc-emit-vetted`) with the words a body-ink line adds, the words that
    // are no text left out and the safe corrections made, `rules`, `comps` and `inks` being the tracer's rules, components and ink layers. Answers the lines made.
    return sc_emit_vetted(olines, owords, osyms, nsel, page, rotmed, scr, words, lines, etext, rules, comps, inks);
}
pub fn sc_sel_set(mut scr: &mut crate::port::Cells, k: i32, row: i32) -> i32 {
    crate::port::cells_set(scr, sc_sel_base() + k, row);
    return 0;
}
pub fn sc_page_view(mut epages: &mut crate::port::Cells, mut views: &mut crate::port::Cells, mut images: &mut crate::port::Cells, page: i32, decreq: i32, wcpt: i32, hcpt: i32, pxw: i32, pxh: i32, dpi100: i32, cropx: i32, cropy: i32, obj: i32, ix0: i32, iy0: i32, ix1: i32, iy1: i32) -> i32 {
    // The first half of a page of OCR: the image's placement, the page's `epages` row and the `views` row of the raster that
    // is read (a decode, `decreq` its request, `pxw x pxh` pixels at `dpi100`, its top-left corner at (`cropx`, `cropy`)
    // centipoints). Answers the view's row: P7.4 normalizes the raster (its skew goes to this row) BEFORE the OCR answer is
    // mapped through it (`sc-page-evidence`), as SPEC 8.2 says.
    im_new(images, page, ix0, iy0, ix1, iy1, obj, pxw, pxh);
    let ep: i32 = ep_new(epages, page, wcpt, hcpt);
    ep_set(epages, ep, epf_flags(), eg_raster());
    ep_set(epages, ep, epf_dpi(), dpi100);
    return vw_new(views, page, vk_decode(), decreq, -1, pxw, pxh, dpi100, lay_full(), -1, 0, 0, cropx, cropy, 0);
}
pub fn sc_page_evidence(an: &mut crate::port::Cells, at: i32, page: i32, request: i32, vdec: i32, dpi100: i32, lang: i32, mut views: &mut crate::port::Cells, epages: &mut crate::port::Cells, mut etext: &mut crate::port::Cells, mut oruns: &mut crate::port::Cells, mut oblocks: &mut crate::port::Cells, mut olines: &mut crate::port::Cells, mut owords: &mut crate::port::Cells, mut osyms: &mut crate::port::Cells, mut oalts: &mut crate::port::Cells, mut feats: &mut crate::port::Cells) -> i32 {
    // The second half: the OCR answer at `at` as the page's evidence (the run with everything under it, and the engine's
    // thresholded image as a view of its own when the answer says it carries one), mapped through the view `vdec`. Answers the
    // run's row. The pipeline's lines are `sc-emit-lines`' or `sc-emit-sel`'s.
    let cropx: i32 = vw_get(views, vdec, vwf_cropx());
    let cropy: i32 = vw_get(views, vdec, vwf_cropy());
    let run: i32 = sc_answer(an, at, page, vdec, request, lang, views, epages, etext, oruns, oblocks, olines, owords, osyms, oalts, feats);
    let ext: i32 = ox_find(an, at);
    let mut vbin: i32 = -1;
    if ext >= 0 {
        if ox_binary(an, ext) == 1 {
            vbin = vw_new(views, page, vk_engine_binary(), request, vdec, ox_bw(an, ext), ox_bh(an, ext), dpi100, lay_full(), -1, 0, 0, cropx, cropy, 1);
            or_set(oruns, run, orf_bview(), vbin);
        }
    }
    return run;
}
pub fn sc_page(an: &mut crate::port::Cells, at: i32, page: i32, request: i32, decreq: i32, wcpt: i32, hcpt: i32, pxw: i32, pxh: i32, dpi100: i32, cropx: i32, cropy: i32, obj: i32, ix0: i32, iy0: i32, ix1: i32, iy1: i32, lang: i32, mut epages: &mut crate::port::Cells, mut views: &mut crate::port::Cells, mut etext: &mut crate::port::Cells, mut feats: &mut crate::port::Cells, mut images: &mut crate::port::Cells, mut oruns: &mut crate::port::Cells, mut oblocks: &mut crate::port::Cells, mut olines: &mut crate::port::Cells, mut owords: &mut crate::port::Cells, mut osyms: &mut crate::port::Cells, mut oalts: &mut crate::port::Cells, mut words: &mut crate::port::Cells, mut lines: &mut crate::port::Cells, mut scr: &mut crate::port::Cells) -> i32 {
    // One page whose OCR answer is at `an`/`at`: the page's evidence (`epages`, the `views` row of the raster read, the image's
    // placement, the run with everything under it, the engine's thresholded image as a view of its own when the answer says
    // it carries one) and its lines in the pipeline's arenas. `decreq` is the decode request that made the bitmap, `request`
    // the OCR request; the raster is `pxw x pxh` at `dpi100` (dots per inch x 100) and its top-left corner is at (`cropx`,
    // `cropy`) centipoints of the page; `obj` is the image's object number (0 none) and (`ix0` `iy0`)-(`ix1` `iy1`) its box.
    // `scr` is scratch (at least 242 cells). Answers the number of OCR lines the pipeline got.
    sc_prep(scr);
    let vdec: i32 = sc_page_view(epages, views, images, page, decreq, wcpt, hcpt, pxw, pxh, dpi100, cropx, cropy, obj, ix0, iy0, ix1, iy1);
    let l0: i32 = ol_count(olines);
    sc_page_evidence(an, at, page, request, vdec, dpi100, lang, views, epages, etext, oruns, oblocks, olines, owords, osyms, oalts, feats);
    let nl: i32 = ol_count(olines) - l0;
    let rotmed: i32 = ev_rot_median(olines, l0, nl);
    return sc_emit_lines(olines, owords, osyms, l0, nl, page, rotmed, scr, words, lines);
}
pub(crate) fn sc_node_page(nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, n: i32) -> i32 {
    // The page of node `n`'s first region, or its nearest ancestor's that has one; -1 when none has.
    let mut t: i32 = n;
    while t >= 0 {
        if node_region_count(nodes, t) > 0 {
            return region_page(regions, node_region_head(nodes, t));
        }
        t = node_parent(nodes, t);
    }
    return -1;
}
pub fn sc_mask_unread() -> i32 {
    // D564: added to a page's `mask` cell when the engine had no model for the page's script (`emon.scriptcheck`).
    return 4;
}
pub fn sc_unread_conf() -> i32 {
    // D564: the most confidence (per mille) a block of a page in a script the engine cannot read keeps.
    return 100;
}
pub fn sc_tag_unread(mut nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, mask: &mut crate::port::Cells) -> i32 {
    // D564: every node whose text is OCR's (`ocr` in its source) on a page the unit marked `sc-mask-unread` (OSD sure of a script that no model the engine read it
    // with reads, `emon.scriptcheck`): a block is flagged `script-unread` and `low-conf`, and every node's confidence is held at `sc-unread-conf`. The text is the
    // engine's guess at a script it cannot read, kept and never presented as confident. After every other provenance stage (the scan's, fusion's). Answers the nodes held.
    let nn: i32 = node_count(nodes);
    let mut n: i32 = 1;
    let mut pg: i32 = 0;
    let mut held: i32 = 0;
    while n < nn {
        pg = sc_node_page(nodes, regions, n);
        if (pg >= 1) && (pg <= crate::port::cells_len(mask)) {
            if (crate::port::cells_at(mask, pg - 1) & sc_mask_unread()) != 0 {
                if (node_src(nodes, n) & sr_ocr()) == sr_ocr() {
                    if nk_is_inline(node_kind(nodes, n)) == 0 {
                        node_add_flag(nodes, n, fl_script_unread());
                        node_add_flag(nodes, n, fl_low_conf());
                    }
                    if node_conf(nodes, n) > sc_unread_conf() {
                        node_set_conf(nodes, n, sc_unread_conf());
                    }
                    held += 1;
                }
            }
        }
        n += 1;
    }
    return held;
}
pub fn sc_write_bare(nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, pages: &mut crate::port::Cells, im: &mut crate::port::Cells, mut ledger: &mut crate::port::Cells) -> i32 {
    // P12.6 (R1): a page of the Model with no node on it and an image of at least a tenth of its area (the biggest such image) gets a ledger row, `background`, for that image, so that a page
    // that comes out empty never has nothing dropped: the image is what it held and was not read, not drawn as a figure and not kept. Answers the rows written.
    let np: i32 = page_count(pages);
    let nn: i32 = node_count(nodes);
    let ni: i32 = im_count(im);
    let mut p: i32 = 0;
    let mut j: i32 = 0;
    let mut n: i32 = 0;
    let mut best: i32 = -1;
    let mut has: i32 = 0;
    let mut rows: i32 = 0;
    let mut area: i64 = 0 as i64;
    let mut bestarea: i64 = 0 as i64;
    while p < np {
        best = -1;
        bestarea = 0 as i64;
        j = 0;
        while j < ni {
            if im_get(im, j, mf_page()) == (p + 1) {
                area = ((im_get(im, j, mf_x1()) - im_get(im, j, mf_x0())) as i64).wrapping_mul((im_get(im, j, mf_y1()) - im_get(im, j, mf_y0())) as i64);
                if (area).wrapping_mul(10 as i64) >= (page_w(pages, p) as i64).wrapping_mul(page_h(pages, p) as i64) {
                    if area > bestarea {
                        best = j;
                        bestarea = area;
                    }
                }
            }
            j += 1;
        }
        if best >= 0 {
            has = 0;
            n = 1;
            while (n < nn) && (has == 0) {
                if sc_node_page(nodes, regions, n) == (p + 1) {
                    has = 1;
                }
                n += 1;
            }
            if has == 0 {
                ledger_add(ledger, dr_background(), p + 1, im_get(im, best, mf_x0()), im_get(im, best, mf_y0()), im_get(im, best, mf_x1()), im_get(im, best, mf_y1()), 600, sr_vector());
                rows += 1;
            }
        }
        p += 1;
    }
    return rows;
}
pub fn sc_tag(mut nodes: &mut crate::port::Cells, mut attrs: &mut crate::port::Cells, mut text: &mut crate::port::Cells, regions: &mut crate::port::Cells, mut pages: &mut crate::port::Cells, mask: &mut crate::port::Cells, policy: i32) -> i32 {
    // The provenance of OCR text, after the paragraphs are built. `mask` has one cell a page: 0 none, 1 an image page was
    // OCR'd, 2 a PDF page was (its kind becomes `scanned`, SPEC 3.4), plus `sc-mask-unread` for a page in a script the engine cannot read (`sc-tag-unread`).
    // Every node on a masked page: its `text` source becomes
    // `ocr`, an inline text's confidence 1000 (a glyph's own) becomes 500 (an engine's word: uncalibrated, D130, Phase 10), and a
    // block that had `text` is flagged `ocr-only`. The root gets `settings.ocr` (`policy` 1 auto, 2 always) when any page was OCR'd.
    let np: i32 = page_count(pages);
    let nn: i32 = node_count(nodes);
    let mut i: i32 = 0;
    let mut any: i32 = 0;
    let mut n: i32 = 1;
    let mut pg: i32 = 0;
    let mut m: i32 = 0;
    let mut s: i32 = 0;
    let mut start: i32 = 0;
    while i < np {
        if (i < crate::port::cells_len(mask)) && ((crate::port::cells_at(mask, i) % 4) >= 1) {
            any = 1;
        }
        if (i < crate::port::cells_len(mask)) && ((crate::port::cells_at(mask, i) % 4) == 2) {
            page_set_kind(pages, i, pk_scanned());
        }
        i += 1;
    }
    if any == 0 {
        return 0;
    }
    while n < nn {
        pg = sc_node_page(nodes, regions, n);
        m = 0;
        if (pg >= 1) && (pg <= crate::port::cells_len(mask)) {
            m = crate::port::cells_at(mask, pg - 1);
        }
        if (m % 4) >= 1 {
            s = node_src(nodes, n);
            if (m & 8) != 0 {
                node_add_flag(nodes, n, fl_rotated());
            }
            if (s & sr_text()) == sr_text() {
                node_set_src(nodes, n, (s - sr_text()) + sr_ocr());
                if nk_is_inline(node_kind(nodes, n)) == 0 {
                    node_add_flag(nodes, n, fl_ocr_only());
                }
                if node_conf(nodes, n) == 1000 {
                    node_set_conf(nodes, n, 500);
                }
            }
        }
        n += 1;
    }
    start = crate::port::cells_len(text);
    if policy == 1 {
        text_append_cp(text, 97);
        text_append_cp(text, 117);
        text_append_cp(text, 116);
        text_append_cp(text, 111);
    }
    if policy == 2 {
        text_append_cp(text, 97);
        text_append_cp(text, 108);
        text_append_cp(text, 119);
        text_append_cp(text, 97);
        text_append_cp(text, 121);
        text_append_cp(text, 115);
    }
    if crate::port::cells_len(text) > start {
        node_set_attr_text(nodes, attrs, 0, fk_ocr(), start, crate::port::cells_len(text) - start);
    }
    return 1;
}
pub(crate) fn sc_native_jpeg(src: &crate::port::Src, start: i32, n: i32) -> i32 {
    // The JPEG subset every ImageDecode host reads for scans: SOF0/1/2, 8-bit, one or three components. Other frames need page rendering; native libraries differ on arithmetic JPEG.
    let mut i: i32 = 2;
    let mut m: i32 = 0;
    let mut size: i32 = 0;
    let mut comps: i32 = 0;
    if n < 4 {
        return 0;
    }
    if (ps_u8(src, start) != 255) || (ps_u8(src, start + 1) != 216) {
        return 0;
    }
    while (i + 4) <= n {
        if ps_u8(src, start + i) != 255 {
            return 0;
        }
        m = ps_u8(src, start + (i + 1));
        if m == 255 {
            i += 1;
        } else if (m == 216) || ((m == 1) || ((m >= 208) && (m <= 215))) {
            i += 2;
        } else {
            if (m == 217) || (m == 218) {
                return 0;
            }
            size = (256 * ps_u8(src, start + (i + 2))) + ps_u8(src, start + (i + 3));
            if (size < 2) || (size > (n - (i + 2))) {
                return 0;
            }
            if (m >= 192) && ((m <= 207) && ((m != 196) && ((m != 200) && (m != 204)))) {
                if (m < 192) || (m > 194) {
                    return 0;
                }
                if size < 8 {
                    return 0;
                }
                if ps_u8(src, start + (i + 4)) != 8 {
                    return 0;
                }
                comps = ps_u8(src, start + (i + 9));
                if (comps == 1) || (comps == 3) {
                    return 1;
                }
                return 0;
            }
            i += size + 2;
        }
    }
    return 0;
}
pub fn sc_dct_span(src: &crate::port::Src, mut ar: &mut crate::port::Cells, mut dc: &mut crate::port::Cells, mut a: &mut crate::port::Cells, mut b: &mut crate::port::Cells, mut st: &mut crate::port::Cells, obj: i32, mut sp: &mut crate::port::Cells) -> i32 {
    // Is object `obj` a stream whose whole filter chain is one DCT stage, in a file that is not encrypted? Then 1 and `sp`
    // holds [start, length] of its bytes in the file: a JPEG stream is a JPEG file, and the host's `ImageDecode` reads it in
    // place. Anything else 0. Loads objects, so `a`, `b` and `st` are overwritten and the source may miss.
    let h: i32 = pd_get(src, ar, dc, a, b, st, obj);
    let mut plan: i32 = 0;
    let mut h0: i32 = 0;
    let mut h1: i32 = 0;
    let mut kt: i32 = 0;
    let mut j: i32 = 0;
    let mut ns: i32 = 0;
    if h == 0 {
        return 0;
    }
    // 8 is the arena kind of a stream (`pl-k-stream`; what `pc-do-image` checks)
    if pl_kind_of(ar, h) != 8 {
        return 0;
    }
    plan = pd_stream_plan(src, ar, dc, a, b, st, h);
    if ps_missed(src) {
        return 0;
    }
    h0 = pl_first(ar, plan);
    h1 = pl_next(ar, h0);
    if pl_int_value(ar, h0) != 0 {
        return 0;
    }
    ns = pl_int_value(ar, h1);
    if ns != 1 {
        return 0;
    }
    kt = pl_next(ar, h1);
    if pl_int_value(ar, kt) != 7 {
        return 0;
    }
    // past the stage's six numbers to the decryption mode: 0 none
    while j < 6 {
        kt = pl_next(ar, kt);
        j += 1;
    }
    if pl_int_value(ar, kt) != 0 {
        return 0;
    }
    if sc_native_jpeg(src, pl_stream_start(ar, h), pl_stream_len(ar, h)) == 0 {
        return 0;
    }
    if ps_missed(src) {
        return 0;
    }
    crate::port::cells_drop(sp, 0);
    crate::port::cells_push(sp, pl_stream_start(ar, h));
    crate::port::cells_push(sp, pl_stream_len(ar, h));
    return 1;
}
pub fn sc_cover_min() -> i32 {
    // P12.6 (R1): the share of a page's area (per mille) that the image of a page with no text at all must cover to be read as the page: a quarter. It was a half, and a 96 dpi book page on an A4 page covers 49.5 per cent of it: the page was dropped, body and ledger empty.
    return 250;
}
pub fn sc_eligible(im: &mut crate::port::Cells, j: i32, pw: i32, ph: i32) -> i32 {
    // Can image placement `j` be OCR'd as the page? Upright and not skewed, a real XObject (not inline, not a stencil
    // mask), at least 16 pixels each way, and covering at least `sc-cover-min` of the page (`pw` x `ph` centipoints) by area. The caller has already seen that the page has no text at all, so the
    // image is what the page holds (the biggest of them, when it has more).
    if im_get(im, j, mf_obj()) <= 0 {
        return 0;
    }
    if im_get(im, j, mf_rot()) != 0 {
        return 0;
    }
    if im_get(im, j, mf_skewed()) != 0 {
        return 0;
    }
    if (im_get(im, j, mf_flags()) & (mg_mask() + mg_inline())) != 0 {
        return 0;
    }
    if im_get(im, j, mf_pxw()) < 16 {
        return 0;
    }
    if im_get(im, j, mf_pxh()) < 16 {
        return 0;
    }
    let area: i64 = ((im_get(im, j, mf_x1()) - im_get(im, j, mf_x0())) as i64).wrapping_mul((im_get(im, j, mf_y1()) - im_get(im, j, mf_y0())) as i64);
    let whole: i64 = (pw as i64).wrapping_mul(ph as i64);
    if (area).wrapping_mul(1000 as i64) < (whole).wrapping_mul(sc_cover_min() as i64) {
        return 0;
    }
    if whole <= (0 as i64) {
        return 0;
    }
    return 1;
}
pub fn sc_word_agreement(ow: &mut crate::port::Cells, et: &mut crate::port::Cells, w: i32) -> i32 {
    // D667: overlapping words from different passes must agree on their text. Ambiguous splits are left alone; a near-identical word box with a different reading reduces trust.
    let mut j: i32 = 0;
    let mut k: i32 = 0;
    let mut same: i32 = 0;
    let n: i32 = ow_get(ow, w, hd_tlen());
    while j < ow_count(ow) {
        if (ow_get(ow, j, owf_run()) != ow_get(ow, w, owf_run())) && ((ow_get(ow, j, hd_page()) == ow_get(ow, w, hd_page())) && (ev_overlap_small(ow_get(ow, w, hd_x0()), ow_get(ow, w, hd_y0()), ow_get(ow, w, hd_x1()), ow_get(ow, w, hd_y1()), ow_get(ow, j, hd_x0()), ow_get(ow, j, hd_y0()), ow_get(ow, j, hd_x1()), ow_get(ow, j, hd_y1())) >= 800)) {
            if ow_get(ow, j, hd_tlen()) == n {
                k = 0;
                same = 1;
                while k < n {
                    if crate::port::cells_at(et, ow_get(ow, w, hd_tstart()) + k) != crate::port::cells_at(et, ow_get(ow, j, hd_tstart()) + k) {
                        same = 0;
                    }
                    k += 1;
                }
                if same == 0 {
                    return 700;
                }
            }
        }
        j += 1;
    }
    return 1000;
}
pub(crate) fn sc_word_base(owords: &mut crate::port::Cells, etext: &mut crate::port::Cells, w: i32) -> i32 {
    let ts: i32 = ow_get(owords, w, hd_tstart());
    let n: i32 = ow_get(owords, w, hd_tlen());
    let flags: i32 = ow_get(owords, w, owf_flags());
    let mut score: i32 = ow_get(owords, w, hd_conf());
    let mut i: i32 = 0;
    let mut latin: i32 = 0;
    let mut rejected: i32 = 0;
    let mut cp: i32 = 0;
    if score < 0 {
        score = 0;
    }
    if score > 1000 {
        score = 1000;
    }
    while i < n {
        cp = crate::port::cells_at(etext, ts + i);
        if ((cp >= 65) && (cp <= 90)) || ((cp >= 97) && (cp <= 122)) {
            latin += 1;
        }
        if (cp == 65533) || (sc_cp_class(cp) == 2) {
            rejected += 1;
        }
        i += 1;
    }
    if (latin >= 3) && ((flags & 3) == 0) {
        score -= 180;
    }
    if sc_implausible(etext, ts, n) == 1 {
        score -= 400;
    }
    if n > 0 {
        score -= (rejected * 600) / n;
    }
    if (flags & oe_garbage()) != 0 {
        if score > 200 {
            score = 200;
        }
    }
    if score < 0 {
        score = 0;
    }
    return score;
}
pub fn sc_word_trust(owords: &mut crate::port::Cells, etext: &mut crate::port::Cells, w: i32) -> i32 {
    return (sc_word_base(owords, etext, w) * sc_word_agreement(owords, etext, w)) / 1000;
}
pub(crate) fn sc_rotated_page(oruns: &mut crate::port::Cells, page: i32) -> i32 {
    let mut r: i32 = 0;
    while r < or_count(oruns) {
        if (or_get(oruns, r, 0) == page) && (or_get(oruns, r, orf_pass()) == op_re_rotated()) {
            return 1;
        }
        r += 1;
    }
    return 0;
}
pub fn sc_trust(mut nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, owords: &mut crate::port::Cells, etext: &mut crate::port::Cells, oruns: &mut crate::port::Cells) -> i32 {
    // D667: pure OCR nodes carry character-weighted word evidence, rather than paragraph/heading constants. Rejected words in their region also lower trust.
    let mut n: i32 = 1;
    let mut r: i32 = 0;
    let mut w: i32 = 0;
    let mut cx: i32 = 0;
    let mut cy: i32 = 0;
    let mut sum: i32 = 0;
    let mut count: i32 = 0;
    let mut weight: i32 = 0;
    let mut score: i32 = 0;
    let mut tagged: i32 = 0;
    let mut rotated: i32 = 0;
    let mut run: i32 = 0;
    let mut eligible: i32 = 0;
    let mut trust: i32 = 0;
    while n < node_count(nodes) {
        if ((node_src(nodes, n) & sr_ocr()) != 0) && ((node_src(nodes, n) & sr_text()) == 0) {
            sum = 0;
            count = 0;
            r = node_region_head(nodes, n);
            while r >= 0 {
                rotated = 0;
                if (node_flags(nodes, n) & fl_rotated()) != 0 {
                    rotated = sc_rotated_page(oruns, region_page(regions, r));
                }
                w = 0;
                while w < ow_count(owords) {
                    cx = (ow_get(owords, w, hd_x0()) + ow_get(owords, w, hd_x1())) / 2;
                    cy = (ow_get(owords, w, hd_y0()) + ow_get(owords, w, hd_y1())) / 2;
                    eligible = 1;
                    // D731: a fused copy is not another reading of its word
                    if ow_get(owords, w, owf_from()) > 0 {
                        eligible = 0;
                    }
                    if rotated == 1 {
                        run = ow_get(owords, w, owf_run());
                        eligible = 0;
                        if (run >= 0) && (run < or_count(oruns)) {
                            if or_get(oruns, run, orf_pass()) == op_re_rotated() {
                                eligible = 1;
                            }
                        }
                    }
                    if ((eligible == 1) && (ow_get(owords, w, hd_page()) == region_page(regions, r))) && (((cx >= region_x0(regions, r)) && (cx <= region_x1(regions, r))) && ((cy >= region_y0(regions, r)) && (cy <= region_y1(regions, r)))) {
                        weight = ow_get(owords, w, hd_tlen());
                        if weight > 40 {
                            weight = 40;
                        }
                        if rotated == 1 {
                            trust = sc_word_base(owords, etext, w);
                        } else {
                            trust = sc_word_trust(owords, etext, w);
                        }
                        sum += weight * trust;
                        count += weight;
                    }
                    w += 1;
                }
                r = region_next(regions, r);
            }
            if count > 0 {
                score = sum / count;
                node_set_conf(nodes, n, score);
                if score < 500 {
                    node_add_flag(nodes, n, fl_low_conf());
                }
                tagged += 1;
            }
        }
        n += 1;
    }
    return tagged;
}
pub fn sc_format_control(cp: i32) -> i32 {
    if (cp == 1564) || ((cp == 8206) || (cp == 8207)) {
        return 1;
    }
    if ((cp >= 8234) && (cp <= 8238)) || ((cp >= 8294) && (cp <= 8297)) {
        return 1;
    }
    return 0;
}
pub fn sc_unspaced(cp: i32) -> i32 {
    if ((cp >= 12352) && (cp <= 12543)) || (((cp >= 13312) && (cp <= 40959)) || ((cp >= 131072) && (cp <= 195103))) {
        return 1;
    }
    return 0;
}
pub fn sc_clean_text(mut nodes: &mut crate::port::Cells, mut text: &mut crate::port::Cells) -> i32 {
    // D669: OCR formatting controls and separators between adjacent Han/Kana characters are not content. Repoint only changed OCR text runs.
    let mut n: i32 = 1;
    let mut ts: i32 = 0;
    let mut ncp: i32 = 0;
    let mut i: i32 = 0;
    let mut cp: i32 = 0;
    let mut start: i32 = 0;
    let mut skip: i32 = 0;
    let mut changed: i32 = 0;
    let mut any: i32 = 0;
    while n < node_count(nodes) {
        if (node_src(nodes, n) & sr_ocr()) != 0 {
            ts = node_text_start(nodes, n);
            ncp = node_text_len(nodes, n);
            start = crate::port::cells_len(text);
            i = 0;
            changed = 0;
            while i < ncp {
                cp = crate::port::cells_at(text, ts + i);
                skip = sc_format_control(cp);
                if (cp == 32) && ((i > 0) && ((i + 1) < ncp)) {
                    if (sc_unspaced(crate::port::cells_at(text, ts + (i - 1))) == 1) && (sc_unspaced(crate::port::cells_at(text, ts + (i + 1))) == 1) {
                        skip = 1;
                    }
                }
                if skip == 0 {
                    text_append_cp(text, cp);
                } else {
                    changed = 1;
                }
                i += 1;
            }
            if changed == 1 {
                node_set_text(nodes, n, start, crate::port::cells_len(text) - start);
                any += 1;
            } else {
                crate::port::cells_drop(text, start);
            }
        }
        n += 1;
    }
    return any;
}
pub fn sc_write_empty_regions(olines: &mut crate::port::Cells, nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, mut ledger: &mut crate::port::Cells) -> i32 {
    // D670: a represented ink gap with no Model region over it gets a ledger row, including unread crops and crops held out by the body-ink owner.
    let mut l: i32 = 0;
    let mut n: i32 = 0;
    let mut r: i32 = 0;
    let mut found: i32 = 0;
    let mut rows: i32 = 0;
    while l < ol_count(olines) {
        if ol_get(olines, l, olf_retry_gap()) == 1 {
            found = 0;
            n = 1;
            while (n < node_count(nodes)) && (found == 0) {
                r = node_region_head(nodes, n);
                while (r >= 0) && (found == 0) {
                    if region_page(regions, r) == ol_get(olines, l, hd_page()) {
                        if ev_overlap_small(region_x0(regions, r), region_y0(regions, r), region_x1(regions, r), region_y1(regions, r), ol_get(olines, l, lh_x0()), ol_get(olines, l, lh_y0()), ol_get(olines, l, lh_x1()), ol_get(olines, l, lh_y1())) > 100 {
                            found = 1;
                        }
                    }
                    r = region_next(regions, r);
                }
                n += 1;
            }
            if found == 0 {
                ledger_add(ledger, dr_ocr_ghost(), ol_get(olines, l, hd_page()), ol_get(olines, l, lh_x0()), ol_get(olines, l, lh_y0()), ol_get(olines, l, lh_x1()), ol_get(olines, l, lh_y1()), 0, sr_ocr());
                rows += 1;
            }
        }
        l += 1;
    }
    return rows;
}
pub fn sc_write_empty_ocr(oruns: &mut crate::port::Cells, pages: &mut crate::port::Cells, mut ledger: &mut crate::port::Cells) -> i32 {
    // D698: an explicit ocr-empty diagnostic and dropped region after every attempt on a page returned no words. No text is invented.
    let mut p: i32 = 0;
    let mut r: i32 = 0;
    let mut seen: i32 = 0;
    let mut words: i32 = 0;
    let mut rows: i32 = 0;
    while p < page_count(pages) {
        r = 0;
        seen = 0;
        words = 0;
        while r < or_count(oruns) {
            if or_get(oruns, r, 0) == (p + 1) {
                seen = 1;
                words += or_get(oruns, r, orf_wcount());
            }
            r += 1;
        }
        if (seen == 1) && (words == 0) {
            ledger_add(ledger, dr_ocr_empty(), p + 1, 0, 0, page_w(pages, p), page_h(pages, p), 1000, sr_ocr());
            rows += 1;
        }
        p += 1;
    }
    return rows;
}
pub fn sc_write_rejected_ocr(oruns: &mut crate::port::Cells, pages: &mut crate::port::Cells, nodes: &mut crate::port::Cells, regions: &mut crate::port::Cells, text: &mut crate::port::Cells, mut ledger: &mut crate::port::Cells, mut bag: &mut crate::port::Cells, mut tokens: &mut crate::port::Cells, mut plain: &mut crate::port::Cells) -> i32 {
    // D707: nonempty OCR evidence can still yield no admitted Model text. Keep the page's ocr-empty diagnostic as well as the occurrence ledger.
    let mut p: i32 = 0;
    let mut r: i32 = 0;
    let mut words: i32 = 0;
    let mut rows: i32 = 0;
    while p < page_count(pages) {
        r = 0;
        words = 0;
        while r < or_count(oruns) {
            if or_get(oruns, r, 0) == (p + 1) {
                words += or_get(oruns, r, orf_wcount());
            }
            r += 1;
        }
        if words > 0 {
            if oc_page_text(nodes, regions, text, p + 1, bag, tokens, plain) == 0 {
                ledger_add(ledger, dr_ocr_empty(), p + 1, 0, 0, page_w(pages, p), page_h(pages, p), 1000, sr_ocr());
                rows += 1;
            }
        }
        p += 1;
    }
    return rows;
}
